INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES
(1, 'glowna', 'Strona główna', '<label for=\"katalog-search\">Szukaj:</label>\r\n<input type=\"search\" id=\"katalog-search\" name=\"katalog-searh\">\r\n<p><span id=\"licznik\" aria-live=\"polite\" hidden></span></p>\r\n<p id=\"brak-wynikow\" hidden> Brak dopasowanych produktów</p>\r\n<div class=\"katalog\">\r\n    <article class=\"karta\"> <a href=\"index.php?idp=produkt\">\r\n            <h2>Kettlebell</h2> <img src=\"img/kettle.png\" alt=\"kettle\" width=\"300\" height=\"450\">\r\n            <p>Kettlebell o wadze 16kg wykonany z\r\n                żelaza</p>\r\n            <p>Cena: 200zł</p>\r\n        </a>\r\n    </article>\r\n    <article class=\"karta\">\r\n        <h2>Shaker</h2>\r\n        <img src=\"img/shaker.png\" alt=\"shaker\" width=\"300\" height=\"450\">\r\n        <p> Shaker wykonany z plastiku. Idealny do przygotowywania\r\n            odżywek białkowych </p>\r\n        <p>Cena: 15zł</p>\r\n    </article>\r\n    <article class=\"karta\">\r\n        <h2>Tanktop</h2>\r\n        <img src=\"img/tanktop.png\" alt=\"tanktop\" width=\"300\" height=\"450\">\r\n        <p>Koszulka sportowa typu tanktop wykonana z bawełny</p>\r\n        <p>Cena: 80zł</p>\r\n    </article>\r\n</div>\r\n<h2 id=\"sekcja-demonstracyjna-title\">Sekcja demonstracyjna</h2>\r\n<section id=\"sekcja-demonstracyjna\">\r\n    <button type=\"button\" class=\"demo-button\" id=\"button1-demo\" aria-pressed=\"false\">A</button>\r\n    <button type=\"button\" class=\"demo-button\" id=\"button2-demo\">B</button>\r\n    <button type=\"button\" class=\"demo-button\" id=\"button3-demo\">C</button>\r\n    <div class=\"demo-status\" id=\"status-przycisku\" role=\"status\"></div>\r\n    <button type=\"button\" class=\"demo-button\" id=\"button-reset-demo\" aria-pressed=\"default\">Resetuj A i C</button>\r\n    <button type=\"button\" class=\"demo-button\" id=\"serwer-button\">Sprawdź serwer</button>\r\n    <div class=\"demo-status\" id=\"status-serwera\" role=\"status\"></div>\r\n</section>', 1),
(2, 'kontakt', 'Kontakt', '<form id=\"formularz-kontakt\" method=\"get\" action=\"kontakt.html\">\r\n    <div>\r\n        <label for=\"input-email\">Proszę podać E-mail :</label>\r\n        <input type=\"email\" id=\"input-email\" name=\"email\" required>\r\n    </div>\r\n    <div>\r\n        <label for=\"input-produkt\">Którego produktu dotyczy zapytanie? :</label>\r\n        <select id=\"input-produkt\" name=\"produkt\" required>\r\n            <option value=\"\">Wybierz produkt</option>\r\n            <option value=\"produkt1\">Kettlebell</option>\r\n            <option value=\"produkt2\">Shaker</option>\r\n            <option value=\"produkt3\">Tanktop</option>\r\n        </select>\r\n    </div>\r\n    <div>\r\n        <label for=\"input-ilosc\">Liczba sztuk produktu (1-5):</label>\r\n        <input type=\"number\" id=\"input-ilosc\" name=\"ilosc\" required min=\"1\" max=\"5\" step=\"1\">\r\n        <p id=\"wartosc-zapytania\"></p>\r\n    </div>\r\n    <div>\r\n        <label for=\"input-wiadomosc\">Proszę opisać zapytanie (10-500 znaków):</label>\r\n        <textarea id=\"input-wiadomosc\" name=\"wiadomosc\" required minlength=\"10\" maxlength=\"500\"></textarea>\r\n    </div>\r\n    <p id=\"blad-wiadomosc\" hidden>Proszę podać wiadomość z minimum 10 znaków</p>\r\n    <div>\r\n        <button type=\"submit\">Sprawdź zapytanie</button>\r\n    </div>\r\n    <div id=\"podglad\" hidden>\r\n        <h2>Podgląd zapytania</h2>\r\n        <p>Produkt: <span id=\"podglad-produkt\"></span></p>\r\n        <p>Liczba sztuk: <span id=\"podglad-ilosc\"></span></p>\r\n        <p>Wartość zapytania: <span id=\"podglad-wartosc\"></span></p>\r\n        <p>Wiadomość: <span id=\"podglad-wiadomosc\"></span></p>\r\n    </div>\r\n</form>', 1),
(3, 'produkt', 'Produkt', '<p>Kettlebell żelazny <strong>idealny</strong> do treningów siłowych. Nada się dla początkujących jak i dla zawansowanych użytkowników siłowni.</p>\r\n<p>Cena: 200zł</p>\r\n<article class=\"karta-produkt\">\r\n<img src=\"img/kettle.png\" alt=\"kettlebel16kg\" width=\"300\" height=\"450\">\r\n</article>\r\n<h2>Cechy produktu</h2>\r\n<li> Ciężki lub lekki (zależy od ćwiczącego) </li>\r\n<li> Poręczny </li>\r\n<li> Wytrzymały </li>\r\n<table>\r\n    <caption><strong>Parametry techniczne</strong></caption>\r\n    <thead>\r\n        <tr>\r\n            <th scope=\"col\">Parametr</th>\r\n            <th scope=\"col\">Wartość</th>\r\n        </tr>\r\n    </thead>\r\n    <tbody>\r\n        <tr>\r\n            <td>Waga</td>\r\n            <td>16kg</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Materiał</td>\r\n            <td>Żelazo</td>\r\n        </tr>\r\n        <tr>\r\n            <td>Wysokość</td>\r\n            <td>30cm</td>\r\n        </tr>\r\n    </tbody>\r\n</table>\r\n<a href=\"index.php?idp=kontakt\"> Zapytaj o produkt </a>', 1),
(4, 'filmy', 'Filmy', '<div class=\"film\">\r\n    <h1>Porady dla początkujących na siłowni</h1>\r\n    <iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/U9ENCvFf9yQ?si=v6V_rXWCFFKdWUzw\" title=\"Porady dla początkujących na siłowni\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\r\n    <a href=\"https://www.youtube.com/watch?v=U9ENCvFf9yQ\">Źródło</a>\r\n</div>\r\n<div class=\"film\">\r\n    <h1>10 Ćwiczeń z kettlebell</h1>\r\n    <iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/qQNvxEOhRBM?si=gB2_s2h2Dtq-jfCh\" title=\"10 ćwieczeń z kettlebell\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen aspect-ratio=200x200></iframe>\r\n    <a href=\"https://www.youtube.com/watch?v=qQNvxEOhRBM\">Źródło</a>\r\n</div>\r\n<div class=\"film\">\r\n    <h1>Jak przygotować shake proteinowy</h1>\r\n    <iframe width=\"560\" height=\"315\" src=\"https://www.youtube.com/embed/Gh9Dv5D5aCM?si=3w745PRN6QPodbe0\" title=\"Jak przygotować shake proteinowy\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>\r\n    <a href=\"https://www.youtube.com/watch?v=Gh9Dv5D5aCM\">Źródło</a>\r\n</div>', 0);